package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Bounded discovery projections; no catalog grants execution authority. */
public final class ModelDiscoveryService {
    public static final int MAX_MODELS=5000,MAX_BYTES=1048576;
    private final Map<String,String> environment;
    public ModelDiscoveryService(){this(System.getenv());}
    public ModelDiscoveryService(Map<String,String> environment){this.environment=Map.copyOf(environment);}
    public static boolean isBoundedModelId(String id){return id!=null&&id.length()>0&&id.length()<=256&&id.matches("[A-Za-z0-9][A-Za-z0-9._/\\-:@+]*");}
    public static URI validateUrl(String raw){try{if(raw==null||raw.isBlank()||raw.length()>2048)throw new IllegalArgumentException();URI u=URI.create(raw.trim());if(!Set.of("http","https").contains(u.getScheme()))throw new RuntimeFailure("unsupported-scheme","Only HTTP(S) catalog URLs are supported");if(u.getHost()==null||u.getRawUserInfo()!=null)throw new IllegalArgumentException();return u;}catch(RuntimeFailure e){throw e;}catch(Exception e){throw new RuntimeFailure("invalid-url","Invalid catalog URL");}}
    public static String normalizeModelSourceBaseUrl(String value){return validateUrl(value).toString().replaceAll("/+$","");}
    public static JsonNode boundedFetch(String url,Map<String,String> headers,int maxBytes,long timeout,int redirects){URI current=validateUrl(url);long deadline=System.nanoTime()+timeout*1000000;for(int hop=0;hop<=redirects;hop++){HttpURLConnection c=null;try{c=(HttpURLConnection)current.toURL().openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(remaining(deadline));c.setReadTimeout(remaining(deadline));c.setRequestMethod("GET");headers.forEach(c::setRequestProperty);int status=c.getResponseCode();if(status>=300&&status<400&&c.getHeaderField("Location")!=null){URI next=current.resolve(c.getHeaderField("Location"));validateUrl(next.toString());if(!origin(current).equals(origin(next))&&headers.keySet().stream().anyMatch(k->k.equalsIgnoreCase("Authorization")))throw new RuntimeFailure("unsupported-redirect","Credential-bearing catalog redirects must keep the same origin");current=next;continue;}if(status==401||status==403)throw new RuntimeFailure("auth-required","Catalog credentials were rejected");if(status<200||status>=300)throw new RuntimeFailure("unreachable","Catalog returned HTTP "+status);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=c.getInputStream()){byte[] chunk=new byte[8192];for(;;){c.setReadTimeout(remaining(deadline));int count=input.read(chunk);if(count<0)break;if(bytes.size()+count>maxBytes)throw new RuntimeFailure("oversized","Catalog response exceeds the byte bound");bytes.write(chunk,0,count);}}try{return Json.parse(bytes.toString(StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeFailure("malformed","Catalog response is not valid JSON");}}catch(SocketTimeoutException e){throw new RuntimeFailure("timeout","Catalog request timed out");}catch(RuntimeFailure e){throw e;}catch(IOException e){throw new RuntimeFailure("unreachable","Catalog endpoint is unreachable");}finally{if(c!=null)c.disconnect();}}throw new RuntimeFailure("unsupported-redirect","Catalog exceeded the redirect bound");}
    private static int remaining(long deadline)throws SocketTimeoutException{long left=(deadline-System.nanoTime())/1000000;if(left<=0)throw new SocketTimeoutException();return (int)Math.min(Integer.MAX_VALUE,Math.max(1,left));}
    private static String origin(URI u){return u.getScheme().toLowerCase(Locale.ROOT)+"//"+u.getHost().toLowerCase(Locale.ROOT)+":"+(u.getPort()<0?(u.getScheme().equals("https")?443:80):u.getPort());}
    public ObjectNode fetchOpenAiCompatibleCatalog(JsonNode input){Map<String,String> headers=new HashMap<>();String ref=Json.text(input,"credentialEnvRef",null);if(ref!=null){String token=environment.get(ref);if(token==null||token.isEmpty())throw new RuntimeFailure("auth-required","Catalog credential reference is unavailable");headers.put("Authorization","Bearer "+token);}JsonNode body=boundedFetch(normalizeModelSourceBaseUrl(Json.text(input,"baseUrl"))+"/models",headers,MAX_BYTES,10000,5);if(!body.path("data").isArray())throw new RuntimeFailure("malformed","Catalog has no data array");ArrayNode models=Json.array();Set<String> seen=new HashSet<>();boolean truncated=false;for(JsonNode item:body.path("data")){if(models.size()>=MAX_MODELS){truncated=true;break;}String id=Json.text(item,"id",null);if(id!=null)id=id.trim();if(isBoundedModelId(id)&&seen.add(id))models.add(Json.object("modelId",id,"source","openai-compatible"));}ObjectNode out=Json.object("sourceId",input.get("sourceId"),"discoveredAt",Instant.now().toString(),"models",models);if(truncated)out.put("truncated",true);return out;}
    public ObjectNode testOpenAiCompatibleSource(JsonNode input){long begin=System.nanoTime();ObjectNode catalog=fetchOpenAiCompatibleCatalog(input);return Json.object("ok",true,"status","AVAILABLE","reasonCode","none","testedAt",Instant.now().toString(),"durationMs",(System.nanoTime()-begin)/1000000,"modelCount",catalog.path("models").size());}
    public static ArrayNode parseOpenCodeModelLines(String stdout,String provider){ArrayNode models=Json.array();Set<String> seen=new HashSet<>();for(String line:stdout.split("\\R")){String id=line.trim();int slash=id.indexOf('/');if(slash<=0||!isBoundedModelId(id)||!seen.add(id))continue;String p=id.substring(0,slash);if(provider!=null&&!p.equals(provider))continue;models.add(Json.object("modelId",id,"providerId",p,"source","opencode"));if(models.size()>=MAX_MODELS)break;}return models;}
    public static ArrayNode parseCodexModels(String stdout){ArrayNode models=Json.array();JsonNode root;try{root=Json.parse(stdout);}catch(Exception e){return models;}JsonNode candidate=root.isObject()?root.path("models"):root;if(!candidate.isArray())return models;Set<String> seen=new HashSet<>();int scanned=0;for(JsonNode item:candidate){if(++scanned>MAX_MODELS)break;String id=item.isTextual()?item.asText():Json.text(item,"id",Json.text(item,"model",Json.text(item,"name",null)));if(id!=null)id=id.trim();if(isBoundedModelId(id)&&seen.add(id))models.add(Json.object("modelId",id,"source","codex"));}return models;}
    public ArrayNode discoverCodexModels(JsonNode cli){ProcessBoundary.Result result=ProcessBoundary.run(Json.text(cli,"command"),List.of("debug","models"),cli.has("cwd")?Path.of(Json.text(cli,"cwd")):null,ProcessBoundary.environment(cli,environment,false),15000,524288);return ok(result)?parseCodexModels(result.stdout()):Json.array();}
    public ArrayNode discoverOpenCodeModels(JsonNode cli,String provider){List<String> args=new ArrayList<>(List.of("models"));if(provider!=null)args.add(provider);ProcessBoundary.Result result=ProcessBoundary.run(Json.text(cli,"command"),args,cli.has("cwd")?Path.of(Json.text(cli,"cwd")):null,ProcessBoundary.environment(cli,environment,false),15000,524288);return ok(result)?parseOpenCodeModelLines(result.stdout(),provider):Json.array();}
    static boolean ok(ProcessBoundary.Result r){return Objects.equals(r.status(),0)&&!r.exceeded()&&!r.timedOut();}
}
